<script setup lang="ts">
import { useLocale } from '../locales';
const { translate } = useLocale();
import {computed,ref} from 'vue';import {useRoute} from 'vue-router';import {Camera,Clock,ShieldCheck} from 'lucide-vue-next';import PageHeader from '../components/PageHeader.vue';import StatusBadge from '../components/StatusBadge.vue';import ConfirmDialog from '../components/ConfirmDialog.vue';import {useVintro} from '../composables/useVintro';const route=useRoute();const {state,updateQuote}=useVintro();const quote=computed(()=>state.quotes.find(q=>q.id===route.params.id)??state.quotes[0]);const action=ref<'Approved'|'Declined'|null>(null);const confirm=()=>{if(action.value)updateQuote(quote.value.id,action.value);action.value=null};const total=computed(()=>quote.value.labour+quote.value.parts.reduce((sum,p)=>sum+p.price,0))
</script>
<template><PageHeader :title="translate('Workshop quote')" back="/quotes"/><div class="container-app max-w-3xl py-7"><div class="flex items-center justify-between"><div><p class="eyebrow">{{ translate((quote.workshop)) }}</p><h1 class="mt-2 text-2xl font-semibold">{{ translate((quote.service)) }}</h1></div><StatusBadge :status="quote.status"/></div><div class="mt-6 flex gap-3 rounded-2xl bg-amber-50 p-4 text-sm"><Clock :size="19" class="shrink-0 text-amber"/><p>{{ translate("Quote expires ") }}<strong>{{ translate((quote.expires)) }}</strong>{{ translate(". No work is approved until you confirm.") }}</p></div><section class="card mt-5 p-5"><h2 class="section-title">{{ translate("Workshop recommendation") }}</h2><p class="mt-3 text-sm leading-6 text-muted">{{ translate((quote.recommendation)) }}</p><button v-if="quote.photos" class="mt-4 flex items-center gap-2 rounded-xl bg-stone-100 px-4 py-3 text-sm font-medium"><Camera :size="17"/>{{ translate("View " + (quote.photos) + " workshop photos") }}</button></section><section class="card mt-5 overflow-hidden"><div class="p-5"><h2 class="section-title">{{ translate("Quote details") }}</h2></div><div class="divide-y border-t"><div class="flex justify-between px-5 py-4 text-sm"><span>{{ translate("Labour") }}</span><strong class="nums">{{ translate("€ " + (quote.labour)) }}</strong></div><div v-for="p in quote.parts" class="flex justify-between px-5 py-4 text-sm"><span>{{ translate((p.name)) }}</span><strong class="nums">{{ translate("€ " + (p.price)) }}</strong></div><div class="flex justify-between bg-stone-50 px-5 py-5"><strong>{{ translate("Total") }}</strong><strong class="nums text-xl">{{ translate("€ " + (total)) }}</strong></div></div></section><div class="mt-5 flex gap-3" v-if="quote.status==='Pending'"><button @click="action='Declined'" class="btn-secondary flex-1">{{ translate("Decline") }}</button><button @click="action='Approved'" class="btn-primary flex-1">{{ translate("Approve work") }}</button></div><div v-else class="mt-5 flex gap-3 rounded-2xl bg-emerald-50 p-5"><ShieldCheck :size="20" class="text-success"/><p class="text-sm">{{ translate("This quote is ") }}<strong>{{ translate((quote.status.toLowerCase())) }}</strong>{{ translate(". The workshop can see your decision.") }}</p></div></div><ConfirmDialog :open="!!action" @close="action=null" @confirm="confirm"><h2 class="text-xl font-semibold">{{ translate((action==='Approved'?'Approve this work?':'Decline this quote?')) }}</h2><p class="mt-2 text-sm leading-6 text-muted">{{ translate("Your decision will be shared with " + (quote.workshop) + ". This remains a local prototype action.") }}</p><template #confirm>{{ translate((action==='Approved'?'Approve work':'Decline quote')) }}</template></ConfirmDialog></template>
